const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let calendarMonth=todayMonth();
function todayMonth(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return p.year+'-'+p.month;}
let S,boot,route='overview',orgFilter='',siteFilter='',filters={},priorFocus,refreshTimer;
const can=(...roles)=>roles.some(r=>S?.user.roles.includes(r));
const staff=()=>can('Administrator','Coordinator','Inspector');
const inspector=()=>can('Inspector')&&S.user.qualified;
const record=id=>S.records.find(r=>r.id===id);
const username=id=>S.users.find(u=>u.id===id)?.name||id||'Unassigned';
const property=id=>record(id)?.name||'Organization-wide';
const organization=id=>S.organizations.find(o=>o.id===id)?.name||id||'Not assigned';
const fmt=(date,timeZone='America/Los_Angeles',dateOnly=false)=>date?new Intl.DateTimeFormat('en-US',{timeZone,month:'short',day:'numeric',year:'numeric',...(dateOnly?{}:{hour:'numeric',minute:'2-digit',timeZoneName:'short'})}).format(new Date(date)):'Not recorded';
const dayFmt=value=>value?new Intl.DateTimeFormat('en-US',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'}).format(new Date(value+'T12:00:00Z')):'Not recorded';
const today=zone=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:zone||'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}-${parts.day}`;};
const due=r=>r.extensions?.at(-1)?.dueDate||r.originalDueDate||'';
const badge=(label,color='')=>`<span class="badge ${color}">${esc(label)}</span>`;
const statusColor=status=>/critical|overdue|denied/i.test(status)?'red':/unknown|unreviewed|missing|draft|not |cancelled/i.test(status)?'gray':/closed|accepted|reviewed|approved|completed|no open|verified/i.test(status)?'green':/review|requested|needed|open|assigned/i.test(status)?'amber':'blue';
const status=s=>badge(s,statusColor(s));
const severity=f=>badge(f.severity+(f.severityReviewed?'':' · unreviewed'),f.severityReviewed?({Critical:'red',High:'amber',Moderate:'amber',Low:'blue'})[f.severity]||'gray':'gray');
const navButton=(label,to,primary=false)=>`<button type="button" data-route="${esc(to)}" class="${primary?'primary':''}">${label}</button>`;
const actionButton=(label,act,identifier='',primary=false)=>`<button type="button" data-act="${act}${identifier?':'+identifier:''}" class="${primary?'primary':''}">${label}</button>`;
const heading=(title,description,actions='')=>`<div class="heading"><div><div class="eyebrow">CSTC CUSTOMER WORKSPACE</div><h1>${title}</h1><p class="sub">${description}</p></div><div class="actions">${actions}</div></div>`;
const empty=text=>`<div class="empty">${text}</div>`;
const inScope=r=>(!orgFilter||r.orgId===orgFilter)&&(!siteFilter||r.siteId===siteFilter||(r.kind==='site'&&r.id===siteFilter));
const list=kind=>S.records.filter(r=>r.kind===kind&&inScope(r));
const teammateOptions=(siteId)=>{const site=record(siteId);return S.users.filter(u=>!u.disabled&&(!site||((u.orgIds.includes('*')||u.orgIds.includes(site.orgId))&&(!u.siteIds.length||u.siteIds.includes(siteId))))).map(u=>[u.id,u.name]);};
const siteOptions=()=>S.records.filter(r=>r.kind==='site'&&(!orgFilter||r.orgId===orgFilter)).map(r=>[r.id,organization(r.orgId)+' · '+r.name]);
const fileOptions=(siteId,purpose)=>S.files.filter(f=>(!siteId||f.site_id===siteId)&&(!purpose||f.purpose===purpose)).map(f=>[f.id,f.name+' · '+f.purpose]);
const selectedSite=()=>siteFilter||siteOptions()[0]?.[0]||'';
function scopedFileLinks(ids=[],images=false){return `<div class="file-list">${ids.map(id=>{const f=S.files.find(f=>f.id===id);return f?`<div><a href="/api/files/${id}" target="_blank" rel="noopener">${esc(f.name)} · ${(f.bytes/1024).toFixed(1)} KB ↗</a><small class="muted"> ${esc(f.purpose)} · SHA-256 recorded</small>${images&&f.mime.startsWith('image/')?`<img src="/api/files/${id}?inline=1" alt="${esc(f.purpose)} attachment: ${esc(f.name)}">`:''}</div>`:'<span class="muted">File awaiting authorized review or unavailable to this role.</span>';}).join('')}</div>`;}
function toast(text){const el=$('#toast');el.textContent=text;el.style.display='block';clearTimeout(el.timer);el.timer=setTimeout(()=>el.style.display='none',6500);}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok){if(r.status===401&&S){S=null;closeDialog();start();}throw Error(data.error||'Request failed.');}return data;}
async function act(fn){try{await fn();}catch(e){toast(e.message);}}
async function refresh(){S=await api('state');render();}
function nav(to){route=to;filters={};render();window.scrollTo(0,0);}
const input=(label,name,value='',type='text',attrs='')=>`<label class="field${type==='textarea'?' full':''}">${label}${type==='textarea'?`<textarea name="${name}" ${attrs}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`}</label>`;
const select=(label,name,value,options,attrs='')=>`<label class="field">${label}<select name="${name}" aria-label="${esc(label)}" ${attrs}>${options.map(o=>{const [v,text]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(text)}</option>`;}).join('')}</select></label>`;
const checkbox=(label,name,value=false,attrs='')=>`<label class="check"><input type="checkbox" name="${name}"${value?' checked':''} ${attrs}>${label}</label>`;
const sourceNotice='<div class="notice full">Record the actual source and scope. Sources are manually reviewed; the app does not verify laws, agency decisions or link availability automatically.</div>';
const readForm=form=>{const data=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(el=>data[el.name]=el.checked);return data;};
function openDialog(title,html,wide=false){priorFocus=document.activeElement;$('#dialogs').innerHTML=`<div class="overlay"><section class="dialog${wide?' wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" class="ghost" id="close-dialog" aria-label="Close dialog">✕</button></div><div class="dialog-body">${html}</div></section></div>`;$('#close-dialog').onclick=closeDialog;$('.dialog input,.dialog select,.dialog button')?.focus();}
function closeDialog(){$('#dialogs').innerHTML='';priorFocus?.focus();}
document.addEventListener('keydown',e=>{if(!$('.dialog'))return;if(e.key==='Escape')closeDialog();if(e.key==='Tab'){const items=$$('.dialog button:not(:disabled),.dialog input:not(:disabled),.dialog select:not(:disabled),.dialog textarea:not(:disabled),.dialog a[href]').filter(el=>el.offsetParent!==null);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
function formDialog(title,html,save,{wide=false,button='Save record'}={}){openDialog(title,`<form id="record-form"><div class="form-grid">${html}</div><div class="form-actions"><button type="button" id="cancel-form">Cancel</button><button type="submit" class="primary" id="save-form">${button}</button></div></form>`,wide);$('#cancel-form').onclick=closeDialog;$('#record-form').onsubmit=e=>{e.preventDefault();const form=e.target;act(async()=>{const button=$('#save-form');button.disabled=true;try{const next=await save(readForm(form),form);closeDialog();S=await api('state');if(typeof next==='string')route=next;render();toast('Saved to the customer workspace.');}finally{if(button.isConnected)button.disabled=false;}});};}
async function uploadFile(file,siteId,purpose,permissionConfirmed){if(!file)throw Error('Choose a file.');if(file.size>10*1024*1024)throw Error('Maximum file size is 10 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});return (await api('files','POST',{siteId,orgId:record(siteId)?.orgId,name:file.name,mime:file.type,data,purpose,permissionConfirmed})).id;}
const uploadField=(label='Upload file',name='upload',multiple=false)=>`<label class="field full">${label}<input type="file" name="${name}" accept="application/pdf,image/png,image/jpeg,image/webp" ${multiple?'multiple':''}><small>PDF, PNG, JPEG or WebP, up to 10 MB. Signatures are checked; malware scanning is not configured. Use authorized files only.</small></label>`;
const permissionField=()=>`<div class="full">${checkbox('I have permission to share the selected file(s).','permissionConfirmed',false)}</div>`;
function selectedActions(){return can('Administrator','Coordinator','Inspector')?actionButton('＋ Schedule inspection','new-inspection','',true):'';}
function filterBar(states=[]){return `<div class="filters">${input('Search records','filter-search',filters.search||'','search','placeholder="Title, property or source…"')}${states.length?select('Status','filter-status',filters.status||'',[['','All statuses'],...states]):''}</div>`;}
function searched(rows){return rows.filter(r=>(!filters.search||JSON.stringify([r.title,r.name,r.description,r.source,property(r.siteId)]).toLowerCase().includes(filters.search.toLowerCase()))&&(!filters.status||r.state===filters.status)&&(!filters.createdStart||dateInZone(r.createdAt,'America/Los_Angeles')>=filters.createdStart)&&(!filters.createdEnd||dateInZone(r.createdAt,'America/Los_Angeles')<=filters.createdEnd)&&(!filters.workload||(filters.workload==='pending'?['Open','Assigned'].includes(r.state):filters.workload==='active'?!['Open','Assigned','Closed'].includes(r.state):r.state==='Closed')));}
function render(){
 const page=route.split(':')[0],routes=[['overview','Overview','▦'],['sites','Properties','⌂'],['inspections','Inspections & visits','▤'],['findings','Findings & corrections','⚑'],['reports','Report archive','▧'],['guides','Preparation guides','✓'],['projects','Projects & permits','◇'],['tasks','Prevention & follow-up','↻'],['messages','Messages','✉'],['reminders','Deadlines & renewals','◷'],['metrics','Tracking metrics','▥']];
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brandmark">✧</div><div><strong>CSTC</strong><small>Customer dashboard</small></div></div><div class="nav-label">Inspection workspace</div><nav class="nav">${routes.map(([id,label,mark])=>`<button data-route="${id}" class="${page===id?'active':''}"><span aria-hidden="true">${mark}</span>${label}</button>`).join('')}${can('Administrator')?`<button data-route="team" class="${page==='team'?'active':''}"><span aria-hidden="true">⚙</span>Team & workspace</button>`:''}</nav><div class="side-note"><strong>Evidence before closure</strong><br>Submission, internal verification, re-inspection and external acceptance remain distinct.</div><div class="profile"><strong>${esc(S.user.name)}</strong><small>${esc(S.user.roles.join(' · '))}</small><div class="actions"><button class="ghost small" data-act="logout">Sign out</button></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu ghost" data-act="menu" aria-label="Toggle navigation">☰</button><span class="breadcrumb">Workspace / ${esc(routes.find(r=>r[0]===page)?.[1]||'Record details')}</span><div class="top-actions"><a href="https://www.cstcsafety.com/" target="_blank" rel="noopener">Visit CSTC Safety ↗</a><a href="/prototype/" target="_blank" rel="noopener">Other dashboard tools · prototype ↗</a>${S.demo?`<select id="identity" aria-label="Simulated identity">${boot.users.filter(u=>!u.disabled).map(u=>`<option value="${u.id}"${u.id===S.user.id?' selected':''}>Demo: ${esc(u.name.split(' · ')[0])}</option>`).join('')}</select>`:''}</div></header><div class="ribbon"><span>${S.demo?'DEMONSTRATION · Simulated identities. Seeded records are illustrative; changes persist on this server.':'AUTHENTICATED WORKSPACE · Server-enforced organization and property permissions.'}</span><span>In-app reminders only · No agency integration</span></div><div class="page"><div class="scope"><div class="actions">${select('Organization','scope-org',orgFilter,[['','All permitted organizations'],...S.organizations.map(o=>[o.id,o.name])])}${select('Property','scope-site',siteFilter,[['','All permitted properties'],...siteOptions()])}</div><small class="muted">Updated ${esc(fmt(S.serverTime))}</small></div>${screen()}<div class="legend"><span><i class="dot red"></i>Critical / overdue</span><span><i class="dot amber"></i>Action / review needed</span><span><i class="dot blue"></i>Scheduled / in progress</span><span><i class="dot green"></i>Verified within recorded scope</span><span><i class="dot"></i>Unknown / incomplete</span></div><footer class="footer"><span>CSTC Customer Dashboard · Recorded inspection scope only</span><span>Provisional branding · ${navigator.onLine?'Server connection checked on save':'Offline — saves require reconnection'}</span></footer></div></main></div>`;
 bind();
}
function screen(){const [page,id]=route.split(':');return ({overview,sites:sitesPage,site:()=>siteDetail(id),inspections:inspectionPage,inspection:()=>inspectionDetail(id),findings:findingsPage,finding:()=>findingDetail(id),reports:reportsPage,guides:guidesPage,projects:projectsPage,project:()=>projectDetail(id),tasks:tasksPage,messages:messagesPage,message:()=>messageDetail(id),reminders:remindersPage,metrics:metricsPage,team:teamPage})[page]?.()||empty('Record view not found.');}
function findingRow(f){return `<article class="row"><span class="severity ${f.severityReviewed&&f.severity==='Critical'?'red':'amber'}" aria-hidden="true">!</span><div class="row-main"><div class="split-actions"><h3>${esc(f.title)}</h3><div class="actions">${severity(f)}${status(f.state)}</div></div><p>${esc(property(f.siteId))} · ${esc(f.classification)}<br>Updated: ${esc(fmt(f.updatedAt))}<br>Owner: ${esc(username(f.assignedTo))} · Deadline: ${esc(dayFmt(due(f)))}${due(f)&&due(f)<today(f.zone)&&f.state!=='Closed'?' · OVERDUE':''}</p><p>${esc(f.nextAction)}</p><div class="actions">${navButton('Review finding','finding:'+f.id)}</div></div></article>`;}
function inspectionRow(i){return `<article class="row"><div class="date-tile">${i.scheduledAt?esc(new Intl.DateTimeFormat('en-US',{month:'short',timeZone:i.zone}).format(new Date(i.scheduledAt))):'—'}<b>${i.scheduledAt?esc(new Intl.DateTimeFormat('en-US',{day:'numeric',timeZone:i.zone}).format(new Date(i.scheduledAt))):'—'}</b></div><div class="row-main"><div class="split-actions"><h3>${esc(i.title)}</h3>${status(i.state)}</div><p>${esc(property(i.siteId))} · ${esc(i.type)}<br>${esc(fmt(i.scheduledAt,i.zone))} · ${esc(username(i.owner))}</p><div class="actions">${navButton('Open inspection','inspection:'+i.id)}</div></div></article>`;}
function overview(){const findings=list('finding'),open=findings.filter(f=>f.state!=='Closed'),critical=open.filter(f=>f.severity==='Critical'&&f.severityReviewed),ids=new Set(S.records.filter(inScope).map(r=>r.id)),reminders=S.reminders.filter(r=>ids.has(r.id)),inspections=list('inspection').filter(i=>i.state==='Scheduled').sort((a,b)=>(a.scheduledAt||'z').localeCompare(b.scheduledAt||'z')),pending=open.filter(f=>['Evidence submitted','Correction verified'].includes(f.state));const ordered=[...open].sort((a,b)=>((a.severityReviewed?['Critical','High','Moderate','Low','Unreviewed'].indexOf(a.severity):4)-(b.severityReviewed?['Critical','High','Moderate','Low','Unreviewed'].indexOf(b.severity):4))||(due(a)||'z').localeCompare(due(b)||'z'));
 return heading('Know what needs your attention.','Inspections, findings and the next required action across your properties.',selectedActions())+(critical.length?`<div class="notice red"><strong>${critical.length} reviewed critical finding${critical.length===1?' remains':'s remain'} open.</strong><br>${esc(critical[0].title)} · ${esc(property(critical[0].siteId))}<br>${esc(critical[0].nextAction)}<div class="actions">${navButton('Review critical finding','finding:'+critical[0].id,true)}</div></div>`:'')+`<div class="stats">${[[critical.length,'Critical findings open','Reviewed severity; not closed'],[reminders.filter(r=>r.status==='Overdue').length,'Deadlines overdue','Recorded dates and source status'],[inspections.filter(i=>Date.parse(i.scheduledAt)>=Date.now()&&Date.parse(i.scheduledAt)<=Date.now()+30*86400000).length,'Inspections within 30 days','Scheduled inspections and re-inspections'],[pending.length,'Awaiting verification','Evidence or required acceptance pending']].map(([value,label,note])=>`<section class="stat"><p>${label}</p><strong>${value.toString().padStart(2,'0')}</strong><small>${note}</small></section>`).join('')}</div><div class="grid"><div><section class="panel"><div class="panel-head"><div><h2>Your prioritized action list</h2><p class="sub">Severity and deadline are separate. Closure requires evidence.</p></div>${navButton('All findings','findings')}</div>${ordered.slice(0,5).map(findingRow).join('')||empty('No open findings in the selected records. Missing inspections or requirements can still mean status is unknown.')}</section><section class="panel"><div class="panel-head"><h2>Property status</h2>${navButton('All properties','sites')}</div>${S.summary.sites.filter(s=>record(s.id)&&inScope(record(s.id))).map(s=>`<div class="row"><div class="row-main"><h3>${esc(s.name)}</h3><p>${esc(s.status)}<br>${s.lastReviewedAt?'Last reviewed: '+esc(fmt(s.lastReviewedAt))+' · '+esc(username(s.reviewedBy)):'No reviewed inspection record.'}</p><p>${esc(s.scope)}</p>${navButton('Open property','site:'+s.id)}</div>${status(s.status)}</div>`).join('')||empty('Add a property to establish its inspection history.')}</section></div><div><section class="panel"><div class="panel-head"><h2>Upcoming inspections</h2></div>${inspections.slice(0,4).map(inspectionRow).join('')||empty('No upcoming inspection is recorded. Verify the actual requirements with the responsible party.')}</section><section class="panel"><div class="panel-head"><h2>Deadlines & source checks</h2>${navButton('All reminders','reminders')}</div>${reminders.slice(0,4).map(r=>`<div class="row"><div class="row-main"><h3>${esc(r.title)}</h3><p>${esc(r.kind)} · ${esc(dayFmt(r.date))}<br>${esc(username(r.owner))}</p></div>${status(r.status)}</div>`).join('')||empty('No recorded deadline reminders.')}</section><div class="notice">This view summarizes recorded evidence. “No open findings” does not guarantee legal compliance. Review scope, source, age and missing records.</div></div></div>`;
}
function sitesPage(){return heading('Every property has its own record.','Keep locations, contacts, inspection history and findings together.',can('Administrator','Coordinator')?actionButton('＋ Add property','new-site','',true):'')+`<div class="cards">${list('site').map(s=>{const summary=S.summary.sites.find(x=>x.id===s.id);return `<article class="card">${status(summary?.status||'Unknown / incomplete')}<h2>${esc(s.name)}</h2><p>${esc(organization(s.orgId))}<br>${esc(s.address||'Address not recorded')}<br>Jurisdiction: ${esc(s.jurisdiction||'Not verified')}<br>Contact: ${esc(s.contact||'Not supplied')}</p><div class="actions">${navButton('Open property','site:'+s.id)}</div></article>`;}).join('')||'<div class="card empty">No properties in this scope. Ask your workspace administrator to add or assign a property.</div>'}</div>`;}
function siteDetail(id){const s=record(id);if(!s)return empty('Property unavailable.');const summary=S.summary.sites.find(x=>x.id===id);return heading(esc(s.name),esc(organization(s.orgId)),can('Administrator','Coordinator','Customer Manager')?actionButton('Edit property','edit-site',id):'')+`<div class="notice">${esc(summary?.status||'Unknown / incomplete')} · Recorded inspections/findings only. ${summary?.lastReviewedAt?'Last review: '+esc(fmt(summary.lastReviewedAt)):'No reviewed inspection available.'}</div><section class="panel"><div class="panel-head"><h2>Property details</h2></div><div class="panel-body"><dl class="data-list"><div><dt>Address</dt><dd>${esc(s.address||'Not supplied')}</dd></div><div><dt>Jurisdiction</dt><dd>${esc(s.jurisdiction||'Not verified')}</dd></div><div><dt>Responsible contact</dt><dd>${esc(s.contact||'Not supplied')}</dd></div><div><dt>Property type / verified requirement scope</dt><dd>${esc(s.propertyType||'Not recorded')}<br>${esc(s.requirements||'Not verified')}</dd></div><div><dt>Notes</dt><dd>${esc(s.notes||'None')}</dd></div></dl></div></section><div class="grid"><section class="panel"><div class="panel-head"><h2>Inspection history</h2>${staff()?actionButton('Schedule inspection','new-inspection',id):''}</div>${S.records.filter(r=>r.kind==='inspection'&&r.siteId===id).map(inspectionRow).join('')||empty('No inspections recorded.')}</section><section class="panel"><div class="panel-head"><h2>Open findings</h2></div>${S.records.filter(r=>r.kind==='finding'&&r.siteId===id&&r.state!=='Closed').map(findingRow).join('')||empty('No open finding in these records.')}</section></div>`;}
function inspectionPage(){const rows=searched(list('inspection')).filter(i=>(!filters.type||i.type===filters.type)&&(!filters.owner||i.owner===filters.owner)&&(!filters.start||(i.scheduledAt&&dateInZone(i.scheduledAt,i.zone)>=filters.start))&&(!filters.end||(i.scheduledAt&&dateInZone(i.scheduledAt,i.zone)<=filters.end))).sort((a,b)=>(a.scheduledAt||'z').localeCompare(b.scheduledAt||'z'));return heading('Plan the inspection. Track the outcome.','Calendar days use each appointment’s recorded time zone. Re-inspections link to the original findings.',selectedActions())+filterBar(['Draft','Scheduled','Completed','Reviewed','Cancelled'])+`<div class="filters">${select('Visit type','filter-type',filters.type||'',[['','All types'],'Inspection','Re-inspection','Training','Service visit'])}${select('Coordinator','filter-owner',filters.owner||'',[['','All coordinators'],...S.users.filter(u=>!u.disabled).map(u=>[u.id,u.name])])}${input('Scheduled from','filter-start',filters.start||'','date')}${input('Scheduled through','filter-end',filters.end||'','date')}${select('View','filter-view',filters.view||'list',[['list','List'],['calendar','Month calendar']])}</div>`+(filters.view==='calendar'?inspectionCalendar(rows):`<section class="panel">${rows.map(inspectionRow).join('')||empty('No inspections match. Create an inspection or adjust your filters.')}</section>`);}
function dateInZone(value,zone){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:zone||'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value)).map(p=>[p.type,p.value]));return p.year+'-'+p.month+'-'+p.day;}
function inspectionCalendar(rows){const [year,month]=calendarMonth.split('-').map(Number),days=new Date(Date.UTC(year,month,0)).getUTCDate(),offset=new Date(Date.UTC(year,month-1,1)).getUTCDay();return `<section class="panel"><div class="panel-head"><h2>${esc(new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(calendarMonth+'-15T12:00:00Z')))}</h2><div class="actions">${actionButton('← Previous month','month-prev')}${actionButton('Next month →','month-next')}</div></div><div class="calendar-scroll"><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>'<strong class="weekday">'+d+'</strong>').join('')}${Array.from({length:offset},()=>'<div class="calendar-day blank"></div>').join('')}${Array.from({length:days},(_,n)=>{const day=calendarMonth+'-'+String(n+1).padStart(2,'0'),events=rows.filter(i=>i.scheduledAt&&dateInZone(i.scheduledAt,i.zone)===day);return '<section class="calendar-day" aria-label="'+day+'"><b>'+String(n+1)+'</b>'+events.map(i=>'<button data-route="inspection:'+i.id+'"><strong>'+esc(i.title)+'</strong><small>'+esc(fmt(i.scheduledAt,i.zone))+' · '+esc(i.zone)+'</small><small>'+esc(property(i.siteId))+' · '+esc(i.state)+'</small></button>').join('')+'</section>';}).join('')}</div></div></section><p class="muted">Keyboard-accessible appointment buttons. The List view provides a compact alternative on small screens. Empty days do not establish that no inspection is required.</p>`;}
function inspectionDetail(id){const i=record(id);if(!i)return empty('Inspection unavailable.');const guide=record(i.guideId),findings=S.records.filter(f=>f.kind==='finding'&&f.inspectionId===id);return heading(esc(i.title),esc(property(i.siteId))+' · '+esc(i.type),`${status(i.state)}${staff()&&['Draft','Scheduled'].includes(i.state)?actionButton('Reschedule','schedule',id)+actionButton('Cancel appointment','cancel-inspection',id):''}`)+`<div class="detail-grid"><div><section class="panel"><div class="panel-head"><h2>Inspection details</h2>${inspector()?actionButton('＋ Record finding','new-finding',id,true):''}</div><div class="panel-body"><dl class="data-list"><div><dt>Scheduled date / time zone</dt><dd>${esc(fmt(i.scheduledAt,i.zone))}<br>${esc(i.zone)}</dd></div><div><dt>Coordinator</dt><dd>${esc(username(i.owner))}</dd></div><div><dt>Inspector / organization</dt><dd>${esc(i.inspectorOrganization||'Not verified')} · ${i.inspectorVerified?'Manually verified':'Unverified'}</dd></div><div><dt>Appointment confirmation</dt><dd>${i.customerConfirmation?'Confirmed by '+esc(username(i.customerConfirmation.by))+' · '+esc(fmt(i.customerConfirmation.at)):i.state==='Scheduled'?actionButton('Confirm appointment','confirm-appointment',i.id):'Not applicable'}</dd></div><div><dt>Scope</dt><dd>${esc(i.scope)}</dd></div><div><dt>Source</dt><dd>${esc(i.source)}</dd></div><div><dt>Actual inspection time</dt><dd>${esc(fmt(i.actualAt,i.zone))}</dd></div><div><dt>Report review</dt><dd>${esc(i.outcome||'Not recorded')}<br>${i.reviewedAt?esc(fmt(i.reviewedAt))+' · '+esc(username(i.reviewedBy)):'Awaiting qualified review'}</dd></div></dl>${i.parentId?`<div class="notice blue">Re-inspection of ${esc(record(i.parentId)?.title||i.parentId)}<div class="actions">${navButton('Original inspection','inspection:'+i.parentId)}</div></div>`:''}</div></section><section class="panel"><div class="panel-head"><h2>Findings from this inspection</h2></div>${findings.map(findingRow).join('')||empty('No findings entered. This does not independently establish compliance.')}</section>${commentsPanel(i)}</div><div><section class="panel"><div class="panel-head"><h2>Prepare for the visit</h2>${i.guideId?badge(guide?'Reviewed guide':'Guide needs review',guide?'green':'amber'):badge('Confirm requirements')}</div><div class="panel-body">${guide?`<h3>${esc(guide.title)}</h3><p class="body-copy">${esc(guide.body)}</p><p class="muted">Source: ${esc(guide.source)}<br>Reviewed ${esc(fmt(guide.reviewedAt))}</p>`:'<p class="muted">No approved preparation guide is attached. Ask the coordinator to confirm the applicable requirements.</p>'}</div>${i.prep.map(p=>`<label class="check-row"><input type="checkbox" data-prep="${p.id}" data-inspection="${i.id}"${p.done?' checked':''}><span>${esc(p.title)}<small class="muted"><br>${esc(username(p.owner))} · ${esc(dayFmt(p.dueDate))}</small></span></label>${can('Administrator','Coordinator','Inspector','Customer Manager')?'<div class="panel-body">'+actionButton('Assign preparation milestone','prep-owner',i.id+'~'+p.id)+'</div>':''}`).join('')}<div class="panel-body"><p class="muted">Preparation completion is separate from passing an inspection.</p></div></section><section class="panel"><div class="panel-head"><h2>Reports & revisions</h2></div><div class="panel-body">${i.reportVersions.length?i.reportVersions.map((v,index)=>`<h3>Report version ${index+1} ${v.fileId===i.approvedReportId?'· current approved record':v.reviewedAt?'· historical reviewed version':'· awaiting review'}</h3>${scopedFileLinks([v.fileId])}`).join(''):empty('No report uploaded.')}<div class="actions">${staff()&&i.state!=='Cancelled'?actionButton('Attach completion report','inspection-report',id):''}${inspector()&&i.state==='Completed'?actionButton('Review report','inspection-review',id,true):''}</div></div></section><div class="notice">Manual appointment reminders appear in-app while this page is open. No customer email, SMS or agency submission is sent.</div></div></div>`;}
function findingsPage(){return heading('Findings that lead to action.','Original citations, source evidence, severity and deadlines remain separate from correction status.')+(filters.workload?'<div class="notice blue">Showing '+esc(filters.workload)+' findings. Record creation dates: '+esc(filters.createdStart||'all history')+' through '+esc(filters.createdEnd||'present')+'. '+actionButton('Clear workload filter','clear-workload')+'</div>':'')+filterBar(['Open','Assigned','In progress','Evidence submitted','Changes requested','Correction verified','Closed'])+`<section class="panel">${searched(list('finding')).map(findingRow).join('')||empty('No findings match. Authorized inspectors record findings from an inspection.')}</section>`;}
function commentsPanel(r){return `<section class="panel"><div class="panel-head"><h2>Record conversation</h2></div><div class="panel-body"><div class="thread">${(r.comments||[]).map(c=>`<article><strong>${esc(username(c.actor))}</strong><small class="muted"> · ${esc(fmt(c.at))}</small><p>${esc(c.text)}</p></article>`).join('')||'<p class="muted">No comments yet.</p>'}</div><form data-comment="${r.id}" data-kind="${r.kind}"><label class="field">Comment<textarea name="text" required maxlength="4000"></textarea></label><button type="submit" class="small">Add comment</button></form></div></section>`;}
function findingDetail(id){const f=record(id);if(!f)return empty('Finding unavailable.');const evidence=S.records.filter(e=>e.kind==='evidence'&&e.findingId===id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),latest=evidence.find(e=>e.id===f.latestEvidenceId),canCorrect=staff()||can('Customer Manager')||f.assignedTo===S.user.id,ready=['Open','Assigned','In progress','Changes requested'].includes(f.state),tasks=S.records.filter(t=>t.kind==='task'&&t.findingId===id),similar=S.records.filter(x=>x.kind==='finding'&&x.id!==id&&x.siteId===f.siteId&&x.category===f.category&&x.inspectionId!==f.inspectionId);
 return heading(esc(f.title),esc(property(f.siteId))+' · '+esc(f.classification),`${severity(f)}${status(f.state)}`)+(f.severity==='Critical'&&f.severityReviewed&&f.state!=='Closed'?`<div class="notice red"><strong>Reviewed critical finding remains open.</strong><br>${esc(f.nextAction)}<br>Use approved site procedures and verified emergency contacts for an immediate danger; this portal is not emergency dispatch.</div>`:'')+`<div class="detail-grid"><div><section class="panel"><div class="panel-head"><h2>Original finding & source</h2>${navButton('Inspection','inspection:'+f.inspectionId)}</div><div class="panel-body"><dl class="data-list"><div><dt>Finding reference</dt><dd>${esc(f.id)}</dd></div><div><dt>Location</dt><dd>${esc(f.location)}</dd></div><div><dt>Assigned owner</dt><dd>${esc(username(f.assignedTo))}</dd></div><div><dt>Current recorded deadline</dt><dd>${esc(dayFmt(due(f)))} · ${esc(f.zone)}<br>${esc(f.deadlineType)}</dd></div><div><dt>Original deadline · preserved</dt><dd>${esc(dayFmt(f.originalDueDate))}<br>${esc(f.deadlineSource||'Not supplied')}</dd></div><div><dt>Citation reference / authority</dt><dd>${esc(f.citationReference||'Not an official citation')}<br>${esc(f.authority||'Not supplied')} · ${esc(f.jurisdiction||'Not verified')}</dd></div><div><dt>Source and review</dt><dd>${esc(f.source)}<br>${f.sourceVerifiedAt?'Manually reviewed '+esc(fmt(f.sourceVerifiedAt)):'Source review not recorded'}</dd></div></dl><p class="muted">Severity is a qualified reviewer’s classification within this record, separate from overdue status. Critical/High receive priority; Unreviewed needs assessment. Confirm the issuing authority’s actual severity definitions.</p><div class="section-title">Description & inspector notes</div><p class="body-copy">${esc(f.description)}</p><p class="body-copy">${esc(f.inspectorNotes)}</p>${f.sourceFileId?scopedFileLinks([f.sourceFileId],true):''}<div class="section-title">Reviewed next action</div><p class="body-copy">${esc(f.nextAction)}</p><p class="muted">Source links and requirements are not automatically checked for currency or applicability.</p></div></section><section class="panel"><div class="panel-head"><h2>Proof of correction & review history</h2>${canCorrect&&ready?actionButton('Submit proof of correction','proof',id,true):''}</div><div class="panel-body">${evidence.map(e=>`<section><div class="section-title">${esc(e.state)} · ${esc(fmt(e.submittedAt))}</div><p class="muted">Submitted by ${esc(username(e.submittedBy))}</p><p class="body-copy">${esc(e.note)}</p>${scopedFileLinks(e.fileIds,true)}${e.reviewNote?`<div class="notice blue">${esc(e.reviewNote)}<br>Reviewer: ${esc(username(e.reviewedBy))} · ${esc(fmt(e.reviewedAt))}</div>`:''}</section>`).join('')||empty('No correction evidence has been submitted. Drafts are private to their author.')}</div></section><section class="panel"><div class="panel-head"><h2>Disputes & source clarification</h2>${canCorrect&&f.state!=='Closed'?actionButton('Record a dispute','dispute',id):''}</div><div class="panel-body"><p class="muted">A dispute does not suspend or extend a deadline. Decisions require documentary authority evidence.</p>${(f.disputes||[]).map(d=>'<p class="body-copy">'+esc(d.note)+'</p><p class="muted">'+esc(d.state)+' · '+esc(username(d.by))+' · '+esc(fmt(d.at))+'</p>'+scopedFileLinks(d.fileIds)).join('')}</div></section>${commentsPanel(f)}</div><div><section class="panel"><div class="panel-head"><h2>Correction workflow</h2></div><div class="panel-body"><p class="muted">${esc(f.state)}<br>Re-inspection: ${f.requiredReinspection?'Required; accepted report needed':'Not marked required'}<br>External acceptance: ${f.agencyAcceptanceRequired?'Required documentary acceptance':'Not marked required'}</p><div class="actions">${canCorrect&&['Open','Assigned','Changes requested'].includes(f.state)?actionButton('Start correction','finding-start',id):''}${can('Administrator','Coordinator','Inspector','Customer Manager')&&f.state!=='Closed'?actionButton('Assign owner','assign',id):''}${inspector()&&f.state==='Evidence submitted'&&latest?.submittedBy!==S.user.id?actionButton('Review correction evidence','evidence-review',id,true):''}${inspector()&&f.state==='Correction verified'?actionButton('Verify closure requirements','finding-close',id,true):''}${inspector()&&f.state==='Closed'?actionButton('Reopen with reason','reopen',id):''}</div>${inspector()&&f.state==='Evidence submitted'&&latest?.submittedBy===S.user.id?'<p class="muted">An independent reviewer must verify your own submitted evidence.</p>':''}<div class="section-title">Required follow-through</div><div class="actions">${staff()&&f.requiredReinspection?actionButton('Schedule linked re-inspection','new-reinspection',id):''}${inspector()&&f.agencyAcceptanceRequired?actionButton('Record authority acceptance','acceptance',id):''}${inspector()&&f.state!=='Closed'?actionButton('Record authorized extension','extension',id):''}</div>${f.externalAcceptance?`<div class="notice blue">${esc(f.externalAcceptance.source)}<br>${esc(f.externalAcceptance.authority)} · ${esc(f.externalAcceptance.reference)}<br>${esc(dayFmt(f.externalAcceptance.acceptedAt))}${scopedFileLinks([f.externalAcceptance.fileId])}</div>`:''}${f.extensions.map(e=>`<p class="muted">Extension to ${esc(dayFmt(e.dueDate))}<br>${esc(e.authority)} · ${esc(e.reason)}</p>${scopedFileLinks([e.fileId])}`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Prevention & recurrence</h2>${inspector()?actionButton('Add reviewed task','new-task',id):''}</div><div class="panel-body">${similar.length?`<div class="notice amber">${similar.length} other finding(s) share category “${esc(f.category)}” at this property. This is a similarity flag, not a verified repeat violation.</div>`:'<p class="muted">No other recorded inspection has a matching category at this property.</p>'}${tasks.map(t=>taskCard(t)).join('')||'<p class="muted">No reviewed preventive task recorded.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Audit trail</h2></div><div class="panel-body timeline">${S.activity.filter(a=>a.record_id===id||evidence.some(e=>e.id===a.record_id)).map(a=>`<article><strong>${esc(a.action)}</strong><br>${esc(username(a.actor))} · ${esc(fmt(a.at))}</article>`).join('')||'No activity in the loaded history.'}</div></section></div></div>`;
}
function reportsPage(){return heading('A reliable report archive.','Original files, revisions and qualified review stay linked to each inspection.')+filterBar()+`<div class="cards">${searched(list('inspection')).filter(i=>i.reportVersions.length).map(i=>`<article class="card"><h2>${esc(i.title)}</h2><p>${esc(property(i.siteId))} · ${esc(fmt(i.actualAt,i.zone))}</p>${i.reportVersions.map((v,n)=>`<h3>Version ${n+1}</h3>${status(v.reviewedAt?'Reviewed · '+v.outcome:'Awaiting review')}${scopedFileLinks([v.fileId])}`).join('')}<div class="actions">${navButton('Inspection record','inspection:'+i.id)}</div></article>`).join('')||empty('No reports available. Completed inspections need an uploaded report and qualified review before customer download.')}</div>`;}
function guidesPage(){return heading('Prepare with a reviewed guide.','Property-specific instructions require qualified source review. Editing invalidates approval.',staff()?actionButton('＋ Create guide','new-guide','',true):'')+`<div class="cards">${list('guide').map(g=>`<article class="card">${status(g.state)}<h2>${esc(g.title)}</h2><p class="body-copy">${esc(g.body)}</p><p class="muted">${esc(property(g.siteId))}<br>Applies to: ${esc(g.inspectionType||'Confirm actual scope')}<br>Owner: ${esc(username(g.owner||g.reviewedBy))}<br>Source: ${esc(g.source)}<br>${g.reviewedAt?'Reviewed '+esc(fmt(g.reviewedAt)):'Not approved for customer use.'}</p><div class="actions">${staff()?actionButton('Edit guide','edit-guide',g.id):''}${inspector()&&g.state!=='Approved'?actionButton('Approve after review','approve-guide',g.id):''}</div></article>`).join('')||empty('No approved preparation guide in this scope.')}</div>`;}
function projectsPage(){return heading('Plan projects. Verify permit requirements.','An application or internal review does not authorize a project to proceed.',can('Administrator','Coordinator','Inspector','Customer Manager')?actionButton('＋ Add project','new-project','',true):'')+`<div class="cards">${list('project').map(p=>`<article class="card"><h2>${esc(p.title)}</h2><p>${esc(property(p.siteId))}<br>${esc(p.jurisdiction)}<br>${esc(dayFmt(p.start))} – ${esc(dayFmt(p.end))}</p><p class="body-copy">${esc(p.scope)}</p>${navButton('Review permit requirements','project:'+p.id)}</article>`).join('')||empty('No projects recorded. Confirm the jurisdiction and actual job scope before reviewing permit applicability.')}</div>`;}
function projectDetail(id){const p=record(id);if(!p)return empty('Project unavailable.');return heading(esc(p.title),esc(property(p.siteId))+' · '+esc(p.jurisdiction),staff()?actionButton('＋ Potential permit','new-permit',id,true):'')+`<div class="notice amber">Permit applicability must be checked against current official sources and the actual project scope. No portal status is permission to begin work.</div><section class="panel"><div class="panel-body"><p class="body-copy">${esc(p.scope)}</p><p>${esc(dayFmt(p.start))} – ${esc(dayFmt(p.end))}</p></div></section><div class="cards">${S.records.filter(r=>r.kind==='permit'&&r.projectId===id).map(r=>`<article class="card">${status(r.state==='Issued'&&r.expires&&r.expires<today(r.zone)?'Expired':r.state)} ${badge(r.applicabilityReviewed?'Applicability reviewed':'Review required',r.applicabilityReviewed?'blue':'amber')}<h2>${esc(r.title)}</h2><p class="body-copy">${esc(r.reason)}</p><p>${esc(r.authority||'Authority not verified')}<br>Source: ${esc(r.source||'Not supplied')}<br>Owner: ${esc(username(r.owner))}<br>Expiry: ${esc(dayFmt(r.expires))}<br>Application: ${esc(r.applicationReference||'Not recorded')}</p><p class="body-copy">${esc(r.conditions)}</p>${r.documentId?scopedFileLinks([r.documentId]):''}<div class="actions">${inspector()?actionButton('Review applicability / status','permit-review',r.id):''}${['Needs applicability review','Not started','In preparation','Submitted'].includes(r.state)?actionButton('Record application','permit-application',r.id):''}</div></article>`).join('')||empty('No permit review recorded. Missing permits do not imply that none are needed.')}</div>${commentsPanel(p)}`;}
function taskCard(t){return `<article class="card">${status(t.state)} ${badge(t.required?'Required corrective task':'Preventive recommendation',t.required?'amber':'blue')}<h3>${esc(t.title)}</h3><p class="body-copy">${esc(t.body)}</p><p class="muted">Root cause / factors: ${esc(t.rootCause||'Not recorded')}<br>Follow-up: ${esc(t.recurrence||'One time')}<br>Source: ${esc(t.source)}<br>Owner: ${esc(username(t.owner))}<br>Deadline: ${esc(dayFmt(t.dueDate))} · ${esc(t.zone)}</p><div class="actions">${navButton('Linked finding','finding:'+t.findingId)}${t.state!=='Completed'&&(staff()||can('Customer Manager')||t.owner===S.user.id)?actionButton('Mark task completed','task-complete',t.id):''}</div></article>`;}
function tasksPage(){return heading('Prevent repeated problems.','Qualified recommendations and required actions stay distinct. Completing a task never closes its finding.')+`<div class="cards">${list('task').map(taskCard).join('')||empty('No reviewed tasks yet. A qualified inspector can add actions from a finding.')}</div>`;}
function messagesPage(){return heading('Keep the conversation with the record.','Private portal conversations are shared with permitted property members and staff. No email or SMS is sent.',actionButton('＋ New inquiry','new-message','',true))+`<section class="panel">${list('message').map(m=>`<article class="row"><div class="row-main"><h2>${esc(m.title)}</h2><p>${esc(property(m.siteId))} · ${esc(fmt(m.updatedAt))}</p><p>${esc(m.thread.at(-1)?.text)}</p>${navButton('Open conversation','message:'+m.id)}</div>${status(m.state)}</article>`).join('')||empty('No portal inquiries yet. Choose New inquiry to contact your assigned team within this workspace.')}</section>`;}
function messageDetail(id){const m=record(id);if(!m)return empty('Message unavailable.');return heading(esc(m.title),esc(property(m.siteId)),status(m.state))+`<section class="panel"><div class="panel-body">${m.relatedId?navButton('Related '+esc(record(m.relatedId)?.kind),record(m.relatedId)?.kind+':'+m.relatedId):''}<div class="thread">${m.thread.map(t=>`<article><strong>${esc(username(t.actor))}</strong> · ${esc(fmt(t.at))}<p class="body-copy">${esc(t.text)}</p></article>`).join('')}</div><form id="reply-form" data-id="${m.id}">${input('Reply','text','','textarea','required maxlength="4000"')}<button class="primary">Send portal reply</button></form><p class="muted">Stored in the portal. Email and SMS delivery are not configured.</p></div></section>`;}
function remindersPage(){const ids=new Set(S.records.filter(inScope).map(r=>r.id));return heading('Upcoming dates. Clear responsibility.','Reminders are recalculated from current records, extensions and cancellations.',actionButton('＋ Track credential renewal','new-credential','',true))+`<div class="notice blue">${esc(S.notifications)} ${select('My advance reminder window','reminder-lead',S.reminderSettings.leadDays,[7,14,30,60,90].map(n=>[n,n+' days']))} Dates use each record’s displayed time zone. Unverified credential dates request a source review.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Reminder</th><th>Deadline / time zone</th><th>Owner</th><th>Status</th><th>Record</th></tr></thead><tbody>${S.reminders.filter(r=>ids.has(r.id)).map(r=>`<tr><td><strong>${esc(r.title)}</strong><br>${esc(r.kind)} · ${esc(property(r.siteId))}</td><td>${esc(dayFmt(r.date))}<br>${esc(r.zone)}</td><td>${esc(username(r.owner))}</td><td>${status(r.status)}<br>${esc(r.advanceWindow)}</td><td>${['finding','inspection'].includes(record(r.id)?.kind)?navButton('Open',record(r.id).kind+':'+r.id):record(r.id)?.kind==='permit'?navButton('Project','project:'+record(r.id).projectId):'See below / prevention'}</td></tr>`).join('')||'<tr><td colspan="5">No recorded reminders in this scope.</td></tr>'}</tbody></table></div></section><h2 class="section-title">Credentials & renewal sources</h2><div class="cards">${list('credential').map(c=>`<article class="card">${badge(c.reviewed?'Source reviewed':'Verify source',c.reviewed?'blue':'amber')}<h3>${esc(c.title)}</h3><p>${esc(c.issuer)} · ${esc(property(c.siteId))}<br>Expiry: ${esc(dayFmt(c.expires))}<br>Source: ${esc(c.source)}</p><div class="actions">${inspector()?actionButton(c.reviewed?'Record reviewed renewal':'Review credential source',c.reviewed?'credential-renew':'credential-review',c.id):''}</div><p class="muted">A recorded expiry is not independent confirmation that a credential is valid or applicable.</p></article>`).join('')||empty('No credential renewals tracked.')}</div>`;}
function trackingMetrics(){const period=r=>(!filters.start||dateInZone(r.createdAt,'America/Los_Angeles')>=filters.start)&&(!filters.end||dateInZone(r.createdAt,'America/Los_Angeles')<=filters.end),fs=list('finding').filter(period),is=list('inspection').filter(period),median=(field,start)=>{const values=fs.filter(f=>f[field]&&f[start]&&Date.parse(f[field])>=Date.parse(f[start])).map(f=>(Date.parse(f[field])-Date.parse(f[start]))/3600000).sort((a,b)=>a-b);return values.length?((values[Math.floor((values.length-1)/2)]+values[Math.ceil((values.length-1)/2)])/2).toFixed(1)+' h':'Not recorded';};return [['Pending findings',fs.filter(f=>['Open','Assigned'].includes(f.state)).length],['Active corrections',fs.filter(f=>!['Open','Assigned','Closed'].includes(f.state)).length],['Closed findings',fs.filter(f=>f.state==='Closed').length],['Pending inspections',is.filter(i=>i.state==='Draft').length],['Scheduled / active inspections',is.filter(i=>i.state==='Scheduled').length],['Completed inspections',is.filter(i=>['Completed','Reviewed'].includes(i.state)).length],['Critical / high open findings',fs.filter(f=>f.severityReviewed&&['Critical','High'].includes(f.severity)&&f.state!=='Closed').length],['Evidence awaiting review',fs.filter(f=>f.state==='Evidence submitted').length],['Overdue correction deadlines',fs.filter(f=>f.state!=='Closed'&&due(f)&&f.deadlineType!=='Unverified date'&&due(f)<today(f.zone)).length],['Permits expiring in 30 days',list('permit').filter(period).filter(p=>p.state==='Issued'&&p.expires&&p.expires>=today(p.zone)&&Date.parse(p.expires+'T12:00:00Z')<=Date.now()+30*86400000).length],['Reviewed credentials expiring in 30 days',list('credential').filter(period).filter(c=>c.reviewed&&c.expires>=today(c.zone)&&Date.parse(c.expires+'T12:00:00Z')<=Date.now()+30*86400000).length],['Correction reported by current deadline',fs.filter(f=>f.correctedAt&&due(f)&&dateInZone(f.correctedAt,f.zone)<=due(f)).length+' / '+fs.filter(f=>f.correctedAt&&due(f)).length],['Properties without a reviewed inspection',list('site').filter(s=>!S.records.some(i=>i.kind==='inspection'&&i.siteId===s.id&&i.state==='Reviewed')).length],...[7,30,90].map(n=>['Scheduled within '+n+' days',is.filter(i=>i.state==='Scheduled'&&Date.parse(i.scheduledAt)>=Date.now()&&Date.parse(i.scheduledAt)<=Date.now()+n*86400000).length]),...[7,30,90].map(n=>['Re-inspections within '+n+' days',is.filter(i=>i.type==='Re-inspection'&&i.state==='Scheduled'&&Date.parse(i.scheduledAt)>=Date.now()&&Date.parse(i.scheduledAt)<=Date.now()+n*86400000).length]),['Median acknowledgment',median('acknowledgedAt','createdAt')],['Median first staff comment',median('firstResponseAt','createdAt')],['Median reported correction',median('correctedAt','createdAt')],['Median evidence verification',median('verifiedAt','correctedAt')],['Median resolution',median('closedAt','createdAt')]];}
function metricsPage(){const metrics=trackingMetrics(),total=Math.max(1,...metrics.slice(0,3).map(x=>x[1]));return heading('Measure progress within the recorded scope.','Calculated from this workspace’s records, filtered by the selected organization and property.',actionButton('Export CSV','export-metrics'))+`<div class="filters">${input('Record created from · America/Los_Angeles','filter-start',filters.start||'','date')}${input('Record created through · America/Los_Angeles','filter-end',filters.end||'','date')}</div><section class="panel"><div class="panel-head"><h2>Finding workload</h2>${badge(S.demo?'Includes illustrative records':'Workspace records','blue')}</div><div class="panel-body">${metrics.slice(0,3).map(([label,n])=>`<div class="metric-row"><strong>${label}</strong><progress max="${total}" value="${n}" aria-label="${label}: ${n}"></progress><button data-metric="${esc(label)}" aria-label="Open ${esc(label)} records">${n} →</button></div>`).join('')}</div></section><div class="cards">${metrics.slice(3).map(([label,n])=>`<article class="card"><p>${label}</p><h2>${n}</h2></article>`).join('')}</div><div class="notice">Period: records created within the selected dates (America/Los_Angeles); blank dates include all recorded history. Upcoming windows use the current time within that cohort. Counts are records, not equivalent risk scores. Pending = Open/Assigned; active = all other non-closed findings. Timing medians use recorded timestamp pairs only; missing values remain “Not recorded.” Acknowledgment starts when correction starts; first response uses the first staff comment; verification runs from latest proof to approval; resolution runs from creation to closure. Business hours are not excluded. Expiry counts use issued permits and reviewed credential records within 30 days. Property missing-review counts cover the current permitted portfolio. No agency data, external benchmark or legal compliance rate is implied.<br>Source: server database · Updated ${esc(fmt(S.serverTime))}</div>`;}
function teamPage(){if(!can('Administrator'))return empty('Administrator access required.');return heading('Manage the workspace.','Customer membership is enforced by the server. Qualified review is a separate administrator designation.',actionButton('＋ Organization','new-org')+actionButton('＋ Team member','new-user','',true))+`<div class="notice">${S.demo?'Demo identity switching is a simulation. Use a separate, empty shared-mode data directory with passwords for real team authentication.':'Shared mode requires individual credentials. Protect this server with HTTPS, backups and your organization’s access policies.'}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Member / username</th><th>Roles</th><th>Membership</th><th>Access</th></tr></thead><tbody>${S.users.map(u=>`<tr><td>${esc(u.name)}<br>${esc(u.id)}</td><td>${esc(u.roles.join(', '))}${u.qualified?'<br>Designated qualified reviewer':''}</td><td>${u.orgIds.map(o=>esc(o==='*'?'All organizations':organization(o))).join('<br>')}<br>${u.siteIds.length?u.siteIds.map(x=>esc(property(x))).join(', '):'All properties within organization membership'}</td><td>${status(u.disabled?'Disabled':'Active')}${u.id!==S.user.id?'<div class="actions">'+actionButton(u.disabled?'Enable':'Disable','toggle-user',u.id)+actionButton('Reset password','reset-password',u.id)+'</div>':''}</td></tr>`).join('')}</tbody></table></div></section><div class="cards">${S.organizations.map(o=>`<article class="card"><h3>${esc(o.name)}</h3><p>${esc(o.segment)}</p></article>`).join('')}</div>`;}
// Convert wall time in an IANA zone; reject gaps and require an explicit choice for repeated hours.
function zonedInstant(date,time,zone,occurrence=''){if(!date||!time)throw Error('Choose a date and time.');const wall=date+'T'+time.slice(0,5),base=Date.parse(wall+'Z'),matches=[],formatter=new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});for(let offset=-14*60;offset<=14*60;offset+=15){const candidate=new Date(base-offset*60000);if(formatter.format(candidate).replace(' ','T')===wall)matches.push(candidate.toISOString());}matches.sort();if(!matches.length)throw Error('That local time does not exist in this time zone. Choose another time.');if(matches.length>1&&!occurrence)throw Error('This time occurs twice during a daylight-saving change. Choose the first or second occurrence.');return occurrence==='later'?matches.at(-1):matches[0];}
function scheduleFields(value='',zone='America/Los_Angeles'){const parts=value?Object.fromEntries(new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).map(p=>[p.type,p.value])):null;return input('Date','date',parts?`${parts.year}-${parts.month}-${parts.day}`:today(zone),'date','required')+input('Local time','time',parts?`${parts.hour}:${parts.minute}`:'09:00','time','required')+input('Time zone (IANA)','zone',zone,'text','required placeholder="America/Los_Angeles"')+select('Repeated hour during daylight-saving change','occurrence','',[['','Choose only if the hour repeats'],['earlier','First occurrence'],['later','Second occurrence']]);}
