function bind(){
 $$('[data-metric]').forEach(el=>el.onclick=()=>{route='findings';filters={createdStart:filters.start,createdEnd:filters.end};if(el.dataset.metric==='Closed findings'){filters.status='Closed';filters.workload='closed';}if(el.dataset.metric==='Pending findings')filters.workload='pending';if(el.dataset.metric==='Active corrections')filters.workload='active';render();});
 $$('[data-route]').forEach(el=>el.onclick=()=>nav(el.dataset.route));
 $$('[data-act]').forEach(el=>el.onclick=()=>{const [action,id]=el.dataset.act.split(':');act(()=>dispatch(action,id));});
 $('[name="scope-org"]').onchange=e=>{orgFilter=e.target.value;siteFilter='';nav('overview');};
 $('[name="scope-site"]').onchange=e=>{siteFilter=e.target.value;nav('overview');};
 if($('#identity'))$('#identity').onchange=e=>act(async()=>{await api('session','POST',{id:e.target.value});orgFilter='';siteFilter='';route='overview';await refresh();});
 const lead=$('[name="reminder-lead"]');if(lead)lead.onchange=e=>act(async()=>{await api('reminder-settings','POST',{leadDays:Number(e.target.value)});await refresh();toast('Personal in-app reminder window saved. No email/SMS delivery is configured.');});
 const search=$('[name="filter-search"]');if(search)search.oninput=e=>{filters.search=e.target.value;const pos=e.target.selectionStart;render();const next=$('[name="filter-search"]');next.focus();next.setSelectionRange(pos,pos);};
 for(const key of ['type','owner','start','end','view']){const el=$('[name="filter-'+key+'"]');if(el)el.onchange=e=>{filters[key]=e.target.value;render();};}
 const filter=$('[name="filter-status"]');if(filter)filter.onchange=e=>{filters.status=e.target.value;render();};
 $$('[data-prep]').forEach(el=>el.onchange=()=>act(async()=>{const r=record(el.dataset.inspection);try{await api('inspections/'+r.id+'/prepare','POST',{version:r.version,taskId:el.dataset.prep,done:el.checked});await refresh();}catch(e){el.checked=!el.checked;throw e;}}));
 $$('[data-comment]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const r=record(form.dataset.comment);act(async()=>{await api(({finding:'findings',inspection:'inspections',project:'projects'})[r.kind]+'/'+r.id+'/comment','POST',{version:r.version,text:form.elements.text.value});await refresh();});});
 if($('#reply-form'))$('#reply-form').onsubmit=e=>{e.preventDefault();const r=record(e.target.dataset.id);act(async()=>{await api('messages/'+r.id+'/reply','POST',{version:r.version,text:e.target.elements.text.value});await refresh();});};
}
async function start(){clearInterval(refreshTimer);try{boot=await api('bootstrap');if(boot.user){await refresh();refreshTimer=setInterval(()=>{if(!$('.dialog')&&!document.activeElement?.matches('input,textarea,select'))act(refresh);},60000);return;}$('#app').innerHTML=`<main class="login"><section class="card"><div class="brand"><div class="brandmark">✧</div><div><strong>CSTC</strong><small>Customer inspection workspace</small></div></div><h1>Clarity across your properties.</h1><p>Upcoming inspections, source-backed findings and the next action to take.</p><div class="notice">${boot.demo?'DEMONSTRATION · Identity selection is simulated. All seeded records are illustrative. Changes persist on this server.':'Sign in to your organization’s shared inspection workspace.'}</div><form id="signin">${boot.demo?select('Demonstration identity','id','customer-a',boot.users.map(u=>[u.id,u.name])):input('Username','id','','text','required autocomplete="username"')+input('Password','password','','password','required autocomplete="current-password"')}<div class="form-actions"><button class="primary">${boot.demo?'Open demonstration':'Sign in'}</button></div></form><p class="muted">No automatic email/SMS delivery or agency integration. Provisional branding.</p><a href="/prototype/">Open original business tools prototype ↗</a></section></main>`;$('#signin').onsubmit=e=>{e.preventDefault();act(async()=>{await api('session','POST',readForm(e.target));route='overview';orgFilter='';siteFilter='';await start();});};}catch(e){$('#app').innerHTML=`<main class="login"><section class="card"><h1>Workspace unavailable</h1><p>${esc(e.message)}</p><p>Check the server connection, then reload this page. Unsaved form changes cannot be recovered.</p><button id="retry">Try again</button></section></main>`;$('#retry').onclick=start;}}
start();
